module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

    typedef enum logic [1:0] {
        ST_ZERO     = 2'b00,
        ST_ONE      = 2'b01,
        ST_ZERO_INV = 2'b10
    } state_t;

    state_t state, next_state;

    // State register with asynchronous reset
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= ST_ZERO;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        case (state)
            ST_ZERO: begin
                if (x) next_state = ST_ONE;
                else   next_state = ST_ZERO;
            end
            ST_ONE: begin
                if (x) next_state = ST_ZERO_INV;
                else   next_state = ST_ONE;
            end
            ST_ZERO_INV: begin
                if (x) next_state = ST_ZERO_INV;
                else   next_state = ST_ONE;
            end
            default: next_state = ST_ZERO;
        endcase
    end

    // Output logic (Moore machine: output depends only on the current state)
    always_comb begin
        case (state)
            ST_ZERO:     z = 1'b0;
            ST_ONE:      z = 1'b1;
            ST_ZERO_INV: z = 1'b0;
            default:     z = 1'b0;
        endcase
    end

endmodule

